{
  "title": "Detect Cobalt Strike Beacon Traffic",
  "id": "example-sigma-cobalt-strike-beacon",
  "status": "experimental",
  "description": "Detects outbound HTTPS traffic to known Cobalt Strike C2 infrastructure based on uncommon TLS SNI patterns and high entropy payloads.",
  "author": "SOC Team",
  "logsource": {
    "product": "windows",
    "service": "network"
  },
  "detection": {
    "selection": {
      "DestinationPort": 443,
      "NetworkProtocol": "tcp",
      "DestinationIp": "198.51.100.23",
      "ApplicationProtocol": "TLS",
      "TLS_SNI|contains": "c2"
    },
    "condition": "selection"
  },
  "falsepositives": ["Legitimate HTTPS to corporate C2 domains"],
  "level": "high"
}
